/* ---------- Hooks (copied from Trenchcoat's src/internal, so this file stays self-contained) ---------- */

/** A ref callback that fills `own` and the caller's ref (object or callback, incl. React 19 cleanups) */
function useRootRef<T>(own: { current: T | null }, ref: Ref<T> | undefined) {
  return useCallback(
    (el: T | null) => {
      own.current = el;
      const cleanup = typeof ref === "function" ? ref(el) : (ref && (ref.current = el), undefined);
      return () => {
        own.current = null;
        if (typeof cleanup === "function") cleanup();
        else if (typeof ref === "function") ref(null);
        else if (ref) ref.current = null;
      };
    },
    [own, ref],
  );
}

/** True while `ref`'s element intersects the viewport and the tab is visible. Starts true; renders only on a change */
function useOnScreen(ref: RefObject<Element | null>) {
  const [onScreen, setOnScreen] = useState(true);
  useEffect(() => {
    const el = ref.current;
    let inView = true;
    let last = true;
    // Only a real change is set: the observer's first report (visible) costs no render
    const update = () => {
      const next = inView && document.visibilityState !== "hidden";
      if (next !== last) setOnScreen((last = next));
    };
    const io =
      el && typeof IntersectionObserver === "function"
        ? new IntersectionObserver((entries) => {
            inView = entries[entries.length - 1].isIntersecting;
            update();
          })
        : null;
    if (el) io?.observe(el);
    document.addEventListener("visibilitychange", update);
    return () => {
      io?.disconnect();
      document.removeEventListener("visibilitychange", update);
    };
  }, [ref]);
  return onScreen;
}

/**
 * State that a parent may control. `value` defined → controlled: the component shows `value` and only asks for
 * changes through `onChange`. `value` undefined → uncontrolled: it keeps its own state, starting at `defaultValue`,
 * and still reports changes. Whether `onChange` is passed never decides which.
 */
function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (next: T) => void, name?: string) {
  const controlled = value !== undefined;
  // Like React's <input value> without onChange: say so once (in development)
  const warned = useRef(false);
  const env = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env?.NODE_ENV;
  if (controlled && !onChange && !warned.current && env !== "production") {
    warned.current = true;
    console.warn(
      `Trenchcoat: ${name ? `\`${name}\`` : "a value prop"} is set without its change handler, so it can't change. ` +
        "Pass the handler to control it, or use the default… prop for a starting value.",
    );
  }
  const [own, setOwn] = useState(defaultValue);
  const current = controlled ? value : own;
  // Read through refs so the setter is stable and never acts on a stale value
  const latest = useRef(current);
  latest.current = current;
  const report = useRef(onChange);
  report.current = onChange;
  const set = useCallback(
    (next: T | ((prev: T) => T)) => {
      const resolved = typeof next === "function" ? (next as (prev: T) => T)(latest.current) : next;
      if (Object.is(resolved, latest.current)) return;
      if (!controlled) setOwn(resolved);
      latest.current = resolved;
      report.current?.(resolved);
    },
    [controlled],
  );
  return [current, set] as const;
}

/* ---------- Styles ---------- */

const css = /* css */ `
/* Theme: the --tc- fallbacks use light-dark(), which follows color-scheme */
:where([data-tc-theme="system"]) { color-scheme: light dark; }
:where([data-theme="light"], [data-tc-theme="light"]) { color-scheme: light; }
:where(.dark, [data-theme="dark"], [data-tc-theme="dark"]) { color-scheme: dark; }

.ui-wm {
  /* One loop of the band around the border; it runs twice and then rests (WCAG 2.2.2) */
  --tc-world-map-travel: 14s;
  --tc-world-map-loops: 2;
  --tc-world-map-chevron: light-dark(#737373, #8f8f8f);
  --tc-world-map-menu-shadow: light-dark(rgba(0, 0, 0, 0.08), rgba(0, 0, 0, 0.4));
  --tc-world-map-menu-shadow-near: light-dark(rgba(0, 0, 0, 0.05), rgba(0, 0, 0, 0.35));
  --tc-world-map-drop: light-dark(rgba(31, 33, 40, 0.1), rgba(0, 0, 0, 0.45));
  --tc-world-map-land: light-dark(#e8e8e8, #2a2a2d);
  --tc-world-map-focus: light-dark(#ffffff, #46464c);
  --tc-world-map-focus-edge: light-dark(#e2e2e2, rgba(255, 255, 255, 0.12));
  position: relative;
  width: 100%;
  aspect-ratio: 540 / 242;
}
.ui-wm-map,
.ui-wm-art {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

/* One full loop around the coastline every 14 seconds; the offsets keep the layers slightly staggered */
.ui-wm-band {
  animation: ui-wm-travel var(--tc-world-map-travel) linear var(--tc-world-map-loops) forwards;
}
.ui-wm-band--1 {
  animation-delay: -0.42s;
}
.ui-wm-band--2 {
  animation-delay: -0.84s;
}
/* Off screen or in a hidden tab the band holds where it is */
.ui-wm[data-paused] .ui-wm-band { animation-play-state: paused; }
@keyframes ui-wm-travel {
  from {
    stroke-dashoffset: 0;
  }
  to {
    stroke-dashoffset: -1000;
  }
}

/* Switching: the old highlight fades back into the gray world, the new one settles in from slightly smaller */
.ui-wm-layer {
  transform-box: view-box;
}
.ui-wm-layer[data-phase="enter"] {
  animation: ui-wm-in var(--tc-duration-slowest, 560ms) var(--tc-ease-out, cubic-bezier(0.22, 1, 0.36, 1)) both;
}
.ui-wm-layer[data-phase="exit"] {
  animation: ui-wm-out var(--tc-duration-slow, 320ms) var(--tc-ease-in, cubic-bezier(0.4, 0, 1, 1)) both;
}
@keyframes ui-wm-in {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
}
@keyframes ui-wm-out {
  to {
    opacity: 0;
  }
}

/* ---------- Continent menu ---------- */
.ui-wm-switch {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
  padding: var(--tc-space-3, 12px);
  transform: scale(var(--tc-world-map-s, 1));
  transform-origin: 0 0;
  font-family: inherit;
  -webkit-font-smoothing: antialiased;
}
.ui-wm-trigger {
  display: flex;
  align-items: center;
  gap: var(--tc-space-1, 4px);
  height: var(--tc-control-h-sm, 28px);
  margin: 0;
  padding: 0 8px 0 var(--tc-control-px-md, 12px);
  border: 1px solid var(--tc-border-default, light-dark(#ececec, #2a2a2e));
  border-radius: var(--tc-radius-full, 999px);
  background: var(--tc-surface-overlay, light-dark(#ffffff, #232326));
  box-shadow: var(--tc-shadow-control, 0 1px 2px light-dark(rgba(0, 0, 0, 0.05), rgba(0, 0, 0, 0.4)));
  color: var(--tc-text-primary, light-dark(#171717, #ededed));
  font: inherit;
  font-size: var(--tc-control-font-size, 13px);
  font-weight: var(--tc-control-font-weight, 500);
  line-height: var(--tc-line-height-none, 1);
  white-space: nowrap;
  cursor: pointer;
  transition: transform var(--tc-duration-fast, 150ms) var(--tc-ease-out, cubic-bezier(0.22, 1, 0.36, 1));
}
.ui-wm-trigger:active {
  transform: scale(0.96);
}
.ui-wm-trigger:focus-visible {
  outline: var(--tc-focus-ring-width, 2px) solid var(--tc-focus-ring, light-dark(#2f68ff, #6b95ff));
  outline-offset: var(--tc-focus-ring-offset, 2px);
}
.ui-wm-chevron {
  width: 14px;
  height: 14px;
  transition: transform var(--tc-duration-base, 200ms) var(--tc-ease-out, cubic-bezier(0.22, 1, 0.36, 1));
}
.ui-wm-trigger[aria-expanded="true"] .ui-wm-chevron {
  transform: rotate(180deg);
}

/* Opening morphs the panel out of a trigger-sized pill in its top-left corner */
.ui-wm-menu {
  --tc-world-map-morph: var(--tc-duration-slower, 420ms) var(--tc-ease-emphasized, cubic-bezier(0.32, 0.72, 0.24, 1));
  position: absolute;
  top: calc(12px + 28px + 6px);
  left: 12px;
  width: 172px;
  /* the shadow sits on the wrapper, so it follows the morphing shape */
  filter: drop-shadow(0 6px 12px var(--tc-world-map-menu-shadow)) drop-shadow(0 1px 2.5px var(--tc-world-map-menu-shadow-near));
  transition: visibility 0s linear 0s;
}
.ui-wm-menu[data-open="false"] {
  visibility: hidden;
  pointer-events: none;
  transition: visibility 0s linear var(--tc-duration-slow, 320ms);
}
.ui-wm-panel {
  position: relative;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  padding: var(--tc-menu-padding, 4px);
  background: var(--tc-menu-bg, light-dark(#ffffff, #232326));
  border: 1px solid var(--tc-border-default, light-dark(#ececec, #2a2a2e));
  border-radius: var(--tc-menu-radius, 12px);
  /* No outline: focus shows as a ring on the active row instead (the panel keeps focus, rows are activedescendants) */
  outline: none;
  clip-path: inset(0 0 0 0 round var(--tc-menu-radius, 12px));
  transition: clip-path var(--tc-world-map-morph);
}
.ui-wm-menu[data-open="false"] .ui-wm-panel {
  clip-path: inset(0 calc(100% - var(--from-w)) calc(100% - var(--from-h)) 0 round calc(var(--from-h) / 2));
  transition: clip-path var(--tc-duration-slow, 320ms) cubic-bezier(0.4, 0, 0.2, 1);
}
/* The rows fade in once the shape has opened up, and out first when closing */
.ui-wm-panel > * {
  transition:
    opacity var(--tc-duration-base, 200ms) var(--tc-ease-decelerate, cubic-bezier(0, 0, 0.58, 1)) var(--tc-duration-quick, 120ms),
    transform var(--tc-duration-slower, 420ms) var(--tc-ease-out, cubic-bezier(0.22, 1, 0.36, 1)) 60ms;
}
.ui-wm-menu[data-open="false"] .ui-wm-panel > * {
  opacity: 0;
  transition: opacity var(--tc-duration-quick, 120ms) var(--tc-ease-in, cubic-bezier(0.4, 0, 1, 1));
}
.ui-wm-menu[data-open="false"] .ui-wm-option {
  transform: translateY(-4px);
}
.ui-wm-fill {
  position: absolute;
  top: 0;
  left: var(--tc-menu-padding, 4px);
  right: var(--tc-menu-padding, 4px);
  border-radius: var(--tc-menu-item-radius, 8px);
  background: var(--tc-menu-item-hover, light-dark(rgba(0, 0, 0, 0.04), rgba(255, 255, 255, 0.05)));
  pointer-events: none;
  transition:
    transform var(--tc-duration-base, 200ms) var(--tc-ease-out, cubic-bezier(0.22, 1, 0.36, 1)),
    height var(--tc-duration-base, 200ms) var(--tc-ease-out, cubic-bezier(0.22, 1, 0.36, 1)),
    opacity var(--tc-duration-fast, 150ms) var(--tc-ease-decelerate, cubic-bezier(0, 0, 0.58, 1));
}
/* Keyboard: the active row carries the focus ring (≥ 3 : 1), not only the faint fill (WCAG 2.4.7 / 1.4.11) */
.ui-wm-panel:focus-visible .ui-wm-fill {
  box-shadow: inset 0 0 0 var(--tc-focus-ring-width, 2px) var(--tc-focus-ring, light-dark(#2f68ff, #6b95ff));
}
.ui-wm-fill[data-glide="false"] {
  transition: opacity var(--tc-duration-fast, 150ms) var(--tc-ease-decelerate, cubic-bezier(0, 0, 0.58, 1));
}
.ui-wm-option {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--tc-space-2, 8px);
  padding: 7px 8px 7px var(--tc-menu-item-px, 10px);
  border-radius: var(--tc-menu-item-radius, 8px);
  color: var(--tc-text-primary, light-dark(#171717, #ededed));
  font-size: var(--tc-menu-item-font-size, 13px);
  font-weight: var(--tc-font-weight-medium, 500);
  line-height: var(--tc-line-height-snug, 18px);
  cursor: pointer;
}
.ui-wm-option-name {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
}
.ui-wm-check {
  flex: none;
  width: 15px;
  height: 15px;
  opacity: 0;
  transform: scale(0.6);
  transition:
    opacity var(--tc-duration-fast, 150ms) var(--tc-ease-decelerate, cubic-bezier(0, 0, 0.58, 1)),
    transform var(--tc-duration-moderate, 260ms) var(--tc-ease-spring, cubic-bezier(0.34, 1.56, 0.64, 1));
}
.ui-wm-check svg {
  display: block;
  width: 100%;
  height: 100%;
}
.ui-wm-option[aria-selected="true"] .ui-wm-check {
  opacity: 1;
  transform: none;
}


@media (prefers-reduced-motion: reduce) {
  .ui-wm-band,
  .ui-wm-layer[data-phase] {
    animation: none;
  }
  .ui-wm-layer[data-phase="exit"] {
    display: none;
  }
  .ui-wm .ui-wm-menu :is(.ui-wm-panel, .ui-wm-panel > *, .ui-wm-fill, .ui-wm-check),
  .ui-wm .ui-wm-chevron {
    transition: none;
  }
}

/* Theme colours: light-dark() follows the page theme, wherever it comes from */
.ui-wm-land { fill: var(--tc-world-map-land); stroke: var(--tc-world-map-land); }
.ui-wm-focus { fill: var(--tc-world-map-focus); stroke: var(--tc-world-map-focus-edge); }
.ui-wm-drop { flood-color: var(--tc-world-map-drop); flood-opacity: 1; }
.ui-wm-chevron-ink { stroke: var(--tc-world-map-chevron); }
`;
